import base64
import html
import json
import re


def tokenisasi(teks):
    return re.findall(r"[a-z0-9]+", teks.lower())


def normalisasi(token):
    token = SINONIM.get(token, token)
    return None if token in STOPWORD else token


def leksem(teks):
    hasil = []
    for t in tokenisasi(teks):
        n = normalisasi(t)
        if n is not None:
            hasil.append(n)
    return hasil


def bangun_indeks(artikel):
    posting = {}
    for a in artikel:
        for bagian, bobot in ((a["judul"], 1.0), (a["isi"], 0.1)):
            for lx in leksem(bagian):
                per_id = posting.setdefault(lx, {})
                per_id[a["id"]] = per_id.get(a["id"], 0) + bobot
    return {
        "posting": posting,
        "kosakata": sorted(posting),
        "artikel": {a["id"]: a for a in artikel},
    }


def trigram(kata):
    s = "  " + kata.lower() + " "
    return {s[i:i + 3] for i in range(len(s) - 2)}


def similarity(a, b):
    ta, tb = trigram(a), trigram(b)
    return len(ta & tb) / len(ta | tb)


def perbaiki(kata, kosakata):
    terbaik, nilai = None, 0.3
    for k in sorted(kosakata):
        s = similarity(kata, k)
        if s > nilai:
            terbaik, nilai = k, s
    return terbaik


def buat_cuplikan(isi, istilah, lebar=4):
    kata = isi.split()
    cocok = [any(n in istilah for n in leksem(k)) for k in kata]
    pusat = cocok.index(True) if True in cocok else 0
    awal, akhir = max(0, pusat - lebar), min(len(kata), pusat + lebar + 1)
    bagian = []
    for i in range(awal, akhir):
        if cocok[i]:
            depan, inti, belakang = re.fullmatch(r"(\W*)(.*?)(\W*)", kata[i]).groups()
            bagian.append(depan + "[[[" + inti + "]]]" + belakang)
        else:
            bagian.append(kata[i])
    teks = " ".join(bagian)
    if awal > 0:
        teks = "... " + teks
    if akhir < len(kata):
        teks = teks + " ..."
    teks = html.escape(teks)
    return teks.replace("[[[", "<mark>").replace("]]]", "</mark>")


def cari(indeks, kueri, kategori=None, cursor=None, n=3):
    kosong = {"hasil": [], "cursor": None, "saran": None, "facet": {}}
    istilah = leksem(kueri)
    if not istilah:
        return kosong
    posting = indeks["posting"]
    diganti = False
    for i, t in enumerate(istilah):
        if t not in posting:
            baru = perbaiki(t, indeks["kosakata"])
            if baru is None:
                return kosong
            istilah[i], diganti = baru, True

    cocok = set(posting[istilah[0]])
    for t in istilah[1:]:
        cocok &= set(posting[t])
    skor = {i: round(sum(posting[t][i] for t in istilah), 4) for i in cocok}
    artikel = indeks["artikel"]

    hitung = {}
    for i in cocok:
        k = artikel[i]["kategori"]
        hitung[k] = hitung.get(k, 0) + 1
    facet = dict(sorted(hitung.items(), key=lambda x: (-x[1], x[0])))

    urut = sorted((i for i in cocok if kategori is None or artikel[i]["kategori"] == kategori),
                  key=lambda i: (-skor[i], i))
    if cursor:
        c = json.loads(base64.b64decode(cursor))
        urut = [i for i in urut if skor[i] < c["skor"] or (skor[i] == c["skor"] and i > c["id"])]
    halaman = urut[:n]
    berikut = None
    if len(urut) > n:
        akhir = halaman[-1]
        berikut = base64.b64encode(json.dumps({"skor": skor[akhir], "id": akhir}).encode()).decode()

    hasil = [{"id": i, "judul": artikel[i]["judul"], "skor": skor[i],
              "cuplikan": buat_cuplikan(artikel[i]["isi"], set(istilah))} for i in halaman]
    return {"hasil": hasil, "cursor": berikut, "saran": " ".join(istilah) if diganti else None, "facet": facet}


INDEKS = bangun_indeks(ARTIKEL)
print(cari(INDEKS, "saldo"))

