import re


def tokenisasi(teks):
    return [t for t in re.split(r"[^a-z0-9]+", teks.lower()) if t]


def parse_websearch(kueri):
    hasil = {"wajib": [], "frasa": [], "larang": []}
    for isi in re.findall(r'"([^"]*)"', kueri):
        token = tokenisasi(isi)
        if token:
            hasil["frasa"].append(token)
    sisa = re.sub(r'"[^"]*"', " ", kueri)
    for kata in sisa.split():
        kunci = "larang" if kata.startswith("-") else "wajib"
        for tok in tokenisasi(kata):
            if tok != "or":
                hasil[kunci].append(tok)
    return hasil


