def evaluasi(hasil, relevan, k):
    kena = sum(1 for i in hasil[:k] if i in relevan)
    rr = 0.0
    for posisi, i in enumerate(hasil, start=1):
        if i in relevan:
            rr = 1 / posisi
            break
    return {
        "precision": kena / k,
        "recall": kena / len(relevan) if relevan else 0.0,
        "rr": rr,
    }


def mrr(daftar):
    if not daftar:
        return 0.0
    return sum(evaluasi(h, r, len(h) or 1)["rr"] for h, r in daftar) / len(daftar)


